import{apiClient}from"./client";const getUsers=async(e="")=>{return(await apiClient.get("/admin/users",{params:e?{organizationSlug:e}:{}})).data},createUser=async e=>{return(await apiClient.post("/admin/users",e)).data},deleteUser=async(e,a)=>{return(await apiClient.delete(`/admin/users/${e}/`+a)).data},upsertUser=async e=>{return(await apiClient.post("/admin/users",e)).data};export{getUsers,createUser,deleteUser,upsertUser};